from pathlib import Path
import subprocess, tempfile, json
results=[]
with tempfile.TemporaryDirectory(prefix='.adoption-cases-', dir='.') as folder:
    cases={'example':'item,amount\\n\"Service, monthly\",12.50\\nRefund,-2\\n','decimal':'item,amount\\nService,1.234\\nRefund,2.345\\n','invalid':'item,amount\\nService,oops\\n','empty':'item,amount\\nService,\\n','missing':'item,amount\\nService\\n','header':'item,amount\\n','utf8':'item,amount\\nCafé,3\\n'}
    runs=[('help',['--help'])]
    for name, content in cases.items():
        path=Path(folder)/f'{name}.csv'; path.write_text(content,encoding='utf-8')
        runs.append((name,[str(path),'amount']))
        if name=='decimal': runs.append(('rounded',[str(path),'amount','--precision','2']))
        if name=='invalid': runs.append(('invalid-rounded',[str(path),'amount','--precision','2']))
        if name=='example': runs.append(('unknown',[str(path),'absent']))
    for name,args in runs:
        run=subprocess.run(['python3','app.py',*args],capture_output=True,text=True)
        results.append({'case':name,'argv':['python3','app.py',*args],'returncode':run.returncode,'stdout':run.stdout,'stderr':run.stderr})
Path('.standards/contextual-evidence.json').write_text(json.dumps(results,indent=2)+'\\n')
print(json.dumps(results,indent=2))
PY
cat .standards/progress.json; tail -n 6 .standards/events.jsonl"

